{
  "name": "PCAN CAN 总线接口适配器",
  "name_en": "PCAN CAN Bus Interface Adapter",
  "manufacturer": "PEAK-System Technik GmbH",
  "description": "这是一类用于将计算机连接到 CAN 或 CAN FD 网络的 PCAN 硬件接口适配器，常见形式包括 USB、PCI 或其他 PCAN 通道设备。它可用于实验室中与工业控制器、汽车电子节点、机器人部件或其他基于 CAN 的仪器通信，执行报文发送、总线监听、状态诊断、设备识别和总线恢复等任务。",
  "description_en": "This is a PCAN hardware interface adapter used to connect a computer to a CAN or CAN FD network, commonly provided as USB, PCI, or other PCAN channel devices. In laboratories it is used to communicate with industrial controllers, automotive electronics, robotic subsystems, or other CAN-based instruments for message transmission, bus monitoring, status diagnostics, device identification, and bus recovery.",
  "actions": [
    {
      "action_name": "auto-get_api_version",
      "description": "查询 PCAN 接口所使用的 API 版本信息。",
      "description_en": "Get the API version information used by the PCAN interface."
    },
    {
      "action_name": "auto-check_api_version",
      "description": "检查 PCAN 接口 API 版本是否可用或兼容。",
      "description_en": "Check whether the PCAN interface API version is available or compatible."
    },
    {
      "action_name": "auto-status",
      "description": "获取 CAN 总线接口的状态码。",
      "description_en": "Get the status code of the CAN bus interface."
    },
    {
      "action_name": "auto-status_is_ok",
      "description": "检查 CAN 总线接口当前状态是否正常。",
      "description_en": "Check whether the current CAN bus interface status is OK."
    },
    {
      "action_name": "auto-reset",
      "description": "在总线错误后复位 PCAN 接口。",
      "description_en": "Reset the PCAN interface after a bus error."
    },
    {
      "action_name": "auto-get_device_number",
      "description": "获取设备编号。",
      "description_en": "Get the device number."
    },
    {
      "action_name": "auto-set_device_number",
      "description": "设置设备编号。",
      "description_en": "Set the device number."
    },
    {
      "action_name": "auto-send",
      "description": "通过 PCAN 接口发送 CAN 或 CAN FD 报文。",
      "description_en": "Send a CAN or CAN FD message through the PCAN interface."
    },
    {
      "action_name": "auto-flash",
      "description": "打开或关闭设备指示灯闪烁以进行物理识别。",
      "description_en": "Turn device LED flashing on or off for physical identification."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭 PCAN 总线接口通道。",
      "description_en": "Shut down the PCAN bus interface channel."
    },
    {
      "action_name": "auto-fd",
      "description": "获取是否启用 CAN FD 模式。",
      "description_en": "Get whether CAN FD mode is enabled."
    },
    {
      "action_name": "auto-state",
      "description": "获取或设置总线控制器状态，例如主动通信或被动监听模式。",
      "description_en": "Get or set the bus controller state, such as active communication or passive listen-only mode."
    },
    {
      "action_name": "auto-status_string",
      "description": "获取总线状态的文本描述。",
      "description_en": "Get a text description of the bus status."
    },
    {
      "action_name": "auto-bits",
      "description": "获取总线位时序或比特率相关配置。",
      "description_en": "Get the bus bit-timing or bitrate-related configuration."
    }
  ],
  "tag_hints": [
    "CAN bus communication",
    "CAN FD",
    "PEAK-System PCAN",
    "bus diagnostics",
    "message transmission",
    "bus monitoring",
    "industrial automation",
    "automotive electronics"
  ]
}

